<details class="editor-collection-row" <?= $index===0 ? 'open' : '' ?>><summary><strong class="editor-collection-title"><?= e($row[$first] ?? 'ردیف جدید') ?></strong><span aria-hidden="true">+</span></summary><div class="editor-row-fields"><label class="form-group"><span class="form-label"><?= e($firstLabel) ?></span><input class="form-control" data-row-title name="<?= e($collection.'['.$index.']['.$first.']') ?>" value="<?= e($row[$first] ?? '') ?>" maxlength="300"></label><label class="form-group"><span class="form-label"><?= e($secondLabel) ?></span><textarea class="form-textarea" name="<?= e($collection.'['.$index.']['.$second.']') ?>" rows="3" maxlength="5000"><?= e($row[$second] ?? '') ?></textarea></label><?php if($collection==='curriculum'): ?><label class="form-group"><span class="form-label">مدت این بخش (اختیاری)</span><input class="form-control" name="<?= e($collection.'['.$index.'][duration]') ?>" value="<?= e($row['duration'] ?? '') ?>" maxlength="120"></label><?php endif; ?><button class="btn btn--ghost btn--sm" type="button" data-delete-row>حذف این ردیف</button></div></details>
